28	/**
29	 * This visitor is designed to determine the spatial envelope (or BBOX or MBR) of a potentially complex geometry.
30	 * It has two modes:
31	 * <ul>
32	 *     <li>
33	 *         Cartesian mode: The envelope is determined by the minimum and maximum x/y coordinates.
34	 *         Incoming BBOX geometries with minX &gt; maxX are treated as invalid.
35	 *         Resulting BBOX geometries will always have minX &lt;= maxX.
36	 *     </li>
37	 *     <li>
38	 *         Geographic mode: The envelope is determined by the minimum and maximum x/y coordinates,
39	 *         considering the possibility of wrapping the longitude around the dateline.
40	 *         A bounding box can be determined either by wrapping the longitude around the dateline or not,
41	 *         and the smaller bounding box is chosen. It is possible to disable the wrapping of the longitude.
42	 * </ul>
43	 * Usage of this is as simple as:
44	 * <code>
45	 *     Optional&lt;Rectangle&gt; bbox = SpatialEnvelopeVisitor.visit(geometry);
46	 *     if (bbox.isPresent()) {
47	 *         Rectangle envelope = bbox.get();
48	 *         // Do stuff with the envelope
49	 *     }
50	 * </code>
51	 * It is also possible to create the inner <code>PointVisitor</code> separately, as well as use the visitor for multiple geometries.
52	 * <code>
53	 *     PointVisitor pointVisitor = new CartesianPointVisitor();
54	 *     SpatialEnvelopeVisitor visitor = new SpatialEnvelopeVisitor(pointVisitor);
55	 *     for (Geometry geometry : geometries) {
56	 *         geometry.visit(visitor);
57	 *     }
58	 *     if (visitor.isValid()) {
59	 *         Rectangle envelope = visitor.getResult();
60	 *         // Do stuff with the envelope
61	 *     }
62	 * </code>
63	 * Code that wishes to modify the behaviour of the visitor can implement the <code>PointVisitor</code> interface,
64	 * or extend the existing implementations.
65	 */
66	public class SpatialEnvelopeVisitor implements GeometryVisitor<Boolean, RuntimeException> {
67	
68	    private final PointVisitor pointVisitor;
69	
70	    public SpatialEnvelopeVisitor(PointVisitor pointVisitor) {
71	        this.pointVisitor = pointVisitor;
72	    }
73	
74	    /**
75	     * Determine the BBOX without considering the CRS or wrapping of the longitude.
76	     * Note that incoming BBOX's that do cross the dateline (minx>maxx) will be treated as invalid.
77	     */
78	    public static Optional<Rectangle> visitCartesian(Geometry geometry) {
79	        var visitor = new SpatialEnvelopeVisitor(new CartesianPointVisitor());
80	        if (geometry.visit(visitor)) {
81	            return Optional.of(visitor.getResult());
82	        }
83	        return Optional.empty();
84	    }
85	
86	    public enum WrapLongitude {
87	        NO_WRAP,
88	        WRAP
89	    }
90	
91	    /**
92	     * Determine the BBOX assuming the CRS is geographic (eg WGS84) and optionally wrapping the longitude around the dateline.
93	     */
94	    public static Optional<Rectangle> visitGeo(Geometry geometry, WrapLongitude wrapLongitude) {
95	        var visitor = new SpatialEnvelopeVisitor(new GeoPointVisitor(wrapLongitude));
96	        if (geometry.visit(visitor)) {
97	            return Optional.of(visitor.getResult());
98	        }
99	        return Optional.empty();
100	    }
101	
102	    public Rectangle getResult() {
103	        return pointVisitor.getResult();
104	    }
105	
106	    /**
107	     * Visitor for visiting points and rectangles. This is where the actual envelope calculation happens.
108	     * There are two implementations, one for cartesian coordinates and one for geographic coordinates.
109	     * The latter can optionally wrap the longitude around the dateline.
110	     */
111	    public interface PointVisitor {
112	        void visitPoint(double x, double y);
113	
114	        void visitRectangle(double minX, double maxX, double maxY, double minY);
115	
116	        boolean isValid();
117	
118	        Rectangle getResult();
119	
120	        /** To allow for memory optimizations through object reuse, the visitor can be reset to its initial state. */
121	        void reset();
122	    }
123	
124	    /**
125	     * The cartesian point visitor determines the envelope by the minimum and maximum x/y coordinates.
126	     * It also disallows invalid rectangles where minX > maxX.
127	     */
128	    public static class CartesianPointVisitor implements PointVisitor {
129	        private double minX = Double.POSITIVE_INFINITY;
130	        private double maxX = Double.NEGATIVE_INFINITY;
131	        private double maxY = Double.NEGATIVE_INFINITY;
132	        private double minY = Double.POSITIVE_INFINITY;
133	
134	        public double getMinX() {
135	            return minX;
136	        }
137	
138	        public double getMaxX() {
139	            return maxX;
140	        }
141	
142	        public double getMaxY() {
143	            return maxY;
144	        }
145	
146	        public double getMinY() {
147	            return minY;
148	        }
149	
150	        @Override
151	        public void visitPoint(double x, double y) {
152	            minX = Math.min(minX, x);
153	            maxX = Math.max(maxX, x);
154	            maxY = Math.max(maxY, y);
155	            minY = Math.min(minY, y);
156	        }
157	
158	        @Override
159	        public void visitRectangle(double minX, double maxX, double maxY, double minY) {
160	            if (minX > maxX) {
161	                throw new IllegalArgumentException(
162	                    String.format(Locale.ROOT, "Invalid cartesian rectangle: minX (%s) > maxX (%s)", minX, maxX)
163	                );
164	            }
165	            this.minX = Math.min(this.minX, minX);
166	            this.maxX = Math.max(this.maxX, maxX);
167	            this.maxY = Math.max(this.maxY, maxY);
168	            this.minY = Math.min(this.minY, minY);
169	        }
170	
171	        @Override
172	        public boolean isValid() {
173	            return minY != Double.POSITIVE_INFINITY;
174	        }
175	
176	        @Override
177	        public Rectangle getResult() {
178	            return new Rectangle(minX, maxX, maxY, minY);
179	        }
180	
181	        @Override
182	        public void reset() {
183	            minX = Double.POSITIVE_INFINITY;
184	            maxX = Double.NEGATIVE_INFINITY;
185	            maxY = Double.NEGATIVE_INFINITY;
186	            minY = Double.POSITIVE_INFINITY;
187	        }
188	    }
189	
190	    /**
191	     * The geographic point visitor determines the envelope by the minimum and maximum x/y coordinates,
192	     * while allowing for wrapping the longitude around the dateline.
193	     * When longitude wrapping is enabled, the visitor will determine the smallest bounding box between the two choices:
194	     * <ul>
195	     *     <li>Wrapping around the front of the earth, in which case the result will have minx &lt; maxx</li>
196	     *     <li>Wrapping around the back of the earth, crossing the dateline, in which case the result will have minx &gt; maxx</li>
197	     * </ul>
198	     */
199	    public static class GeoPointVisitor implements PointVisitor {
200	        protected double top = Double.NEGATIVE_INFINITY;
201	        protected double bottom = Double.POSITIVE_INFINITY;
202	        protected double negLeft = Double.POSITIVE_INFINITY;
203	        protected double negRight = Double.NEGATIVE_INFINITY;
204	        protected double posLeft = Double.POSITIVE_INFINITY;
205	        protected double posRight = Double.NEGATIVE_INFINITY;
206	
207	        private final WrapLongitude wrapLongitude;
208	
209	        public GeoPointVisitor(WrapLongitude wrapLongitude) {
210	            this.wrapLongitude = wrapLongitude;
211	        }
212	
213	        public double getTop() {
214	            return top;
215	        }
216	
217	        public double getBottom() {
218	            return bottom;
219	        }
220	
221	        public double getNegLeft() {
222	            return negLeft;
223	        }
224	
225	        public double getNegRight() {
226	            return negRight;
227	        }
228	
229	        public double getPosLeft() {
230	            return posLeft;
231	        }
232	
233	        public double getPosRight() {
234	            return posRight;
235	        }
236	
237	        @Override
238	        public void visitPoint(double x, double y) {
239	            bottom = Math.min(bottom, y);
240	            top = Math.max(top, y);
241	            visitLongitude(x);
242	        }
243	
244	        @Override
245	        public void visitRectangle(double minX, double maxX, double maxY, double minY) {
246	            // TODO: Fix bug with rectangle crossing the dateline (see Extent.addRectangle for correct behaviour)
247	            this.bottom = Math.min(this.bottom, minY);
248	            this.top = Math.max(this.top, maxY);
249	            visitLongitude(minX);
250	            visitLongitude(maxX);
251	        }
252	
253	        private void visitLongitude(double x) {
254	            if (x >= 0) {
255	                posLeft = Math.min(posLeft, x);
256	                posRight = Math.max(posRight, x);
257	            } else {
258	                negLeft = Math.min(negLeft, x);
259	                negRight = Math.max(negRight, x);
260	            }
261	        }
262	
263	        @Override
264	        public boolean isValid() {
265	            return bottom != Double.POSITIVE_INFINITY;
266	        }
267	
268	        @Override
269	        public Rectangle getResult() {
270	            return getResult(top, bottom, negLeft, negRight, posLeft, posRight, wrapLongitude);
271	        }
272	
273	        @Override
274	        public void reset() {
275	            bottom = Double.POSITIVE_INFINITY;
276	            top = Double.NEGATIVE_INFINITY;
277	            negLeft = Double.POSITIVE_INFINITY;
278	            negRight = Double.NEGATIVE_INFINITY;
279	            posLeft = Double.POSITIVE_INFINITY;
280	            posRight = Double.NEGATIVE_INFINITY;
281	        }
282	
283	        public static Rectangle getResult(
284	            double top,
285	            double bottom,
286	            double negLeft,
287	            double negRight,
288	            double posLeft,
289	            double posRight,
290	            WrapLongitude wrapLongitude
291	        ) {
292	            assert Double.isFinite(top);
293	            if (posRight == Double.NEGATIVE_INFINITY) {
294	                return new Rectangle(negLeft, negRight, top, bottom);
295	            } else if (negLeft == Double.POSITIVE_INFINITY) {
296	                return new Rectangle(posLeft, posRight, top, bottom);
297	            } else {
298	                return switch (wrapLongitude) {
299	                    case NO_WRAP -> new Rectangle(negLeft, posRight, top, bottom);
300	                    case WRAP -> maybeWrap(top, bottom, negLeft, negRight, posLeft, posRight);
301	                };
302	            }
303	        }
304	
305	        private static Rectangle maybeWrap(double top, double bottom, double negLeft, double negRight, double posLeft, double posRight) {
306	            double unwrappedWidth = posRight - negLeft;
307	            double wrappedWidth = 360 + negRight - posLeft;
308	            return unwrappedWidth <= wrappedWidth
309	                ? new Rectangle(negLeft, posRight, top, bottom)
310	                : new Rectangle(posLeft, negRight, top, bottom);
311	        }
312	    }
313	
314	    private boolean isValid() {
315	        return pointVisitor.isValid();
316	    }
317	
318	    @Override
319	    public Boolean visit(Circle circle) throws RuntimeException {
320	        // TODO: Support circle, if given CRS (needed for radius to x/y coordinate transformation)
321	        throw new UnsupportedOperationException("Circle is not supported");
322	    }
323	
324	    @Override
325	    public Boolean visit(GeometryCollection<?> collection) throws RuntimeException {
326	        collection.forEach(geometry -> geometry.visit(this));
327	        return isValid();
328	    }
329	
330	    @Override
331	    public Boolean visit(Line line) throws RuntimeException {
332	        for (int i = 0; i < line.length(); i++) {
333	            pointVisitor.visitPoint(line.getX(i), line.getY(i));
334	        }
335	        return isValid();
336	    }
337	
338	    @Override
339	    public Boolean visit(LinearRing ring) throws RuntimeException {
340	        for (int i = 0; i < ring.length(); i++) {
341	            pointVisitor.visitPoint(ring.getX(i), ring.getY(i));
342	        }
343	        return isValid();
344	    }
345	
346	    @Override
347	    public Boolean visit(MultiLine multiLine) throws RuntimeException {
348	        multiLine.forEach(line -> line.visit(this));
349	        return isValid();
350	    }
351	
352	    @Override
353	    public Boolean visit(MultiPoint multiPoint) throws RuntimeException {
354	        for (int i = 0; i < multiPoint.size(); i++) {
355	            visit(multiPoint.get(i));
356	        }
357	        return isValid();
358	    }
359	
360	    @Override
361	    public Boolean visit(MultiPolygon multiPolygon) throws RuntimeException {
362	        multiPolygon.forEach(polygon -> polygon.visit(this));
363	        return isValid();
364	    }
365	
366	    @Override
367	    public Boolean visit(Point point) throws RuntimeException {
368	        pointVisitor.visitPoint(point.getX(), point.getY());
369	        return isValid();
370	    }
371	
372	    @Override
373	    public Boolean visit(Polygon polygon) throws RuntimeException {
374	        visit(polygon.getPolygon());
375	        for (int i = 0; i < polygon.getNumberOfHoles(); i++) {
376	            visit(polygon.getHole(i));
377	        }
378	        return isValid();
379	    }
380	
381	    @Override
382	    public Boolean visit(Rectangle rectangle) throws RuntimeException {
383	        pointVisitor.visitRectangle(rectangle.getMinX(), rectangle.getMaxX(), rectangle.getMaxY(), rectangle.getMinY());
384	        return isValid();
385	    }
386	}
